def fix_promotion_notifications(apps, schema_editor):
    NotificationLog = apps.get_model("messaging", "NotificationLog")
    for log in NotificationLog.objects.filter(content__icontains="تمت ترقيتك"):
        student = getattr(log, "student", None)
        belt_str = ""
        content = log.content or ""
        if "إلى حزام " in content:
            belt_str = content.split("إلى حزام ", 1)[-1].rstrip(".").strip()
        elif "حزام " in content:
            belt_str = content.split("حزام ", 1)[-1].rstrip(".").strip()

        if student and getattr(student, "full_name", None):
            if belt_str:
                log.content = f"تمت ترقية الطالب {student.full_name} بنجاح إلى حزام {belt_str}."
            else:
                log.content = f"تمت ترقية الطالب {student.full_name} بنجاح."
        else:
            if belt_str:
                log.content = f"تم تسجيل ترقية حزام جديدة إلى حزام {belt_str}."
            else:
                log.content = "تم تسجيل ترقية حزام جديدة بنجاح."
        log.save(update_fields=["content"])


